UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Chichi Peralta — Pedro René Peralta Soto, born in Santo Domingo on 9 July 1966 — is a Dominican percussionist, singer, composer, arranger and producer. He spent the 1980s and 1990s as a working percussionist, eight of those years in the band of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra 4.40","occurrenceId":"f2675a1b-29b3-4078-9c46-4e30b5aa89ac"}},{"text":", before launching Chichi Peralta y Son Familia and taking a Latin Grammy in 2001 for ...De vuelta al barrio.","type":"text"}]},{"type":"paragraph","content":[{"text":"A tambora at four","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Peralta dates his start to the age of four, when he built his first instrument, a tambora. Through the eighties and nineties he played percussion professionally: first with Grupo Fragmento, then seven years with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"29832daf-f093-4ccb-820d-441cdc3f48c0","displayText":"Fernando Echavarría","occurrenceId":"7caf46c1-dc6b-4824-a68e-5a5570561958"}},{"text":" and la Familia André, then in Trilogía, the fusion trio ","type":"text"},{"type":"artistReference","attrs":{"artistId":"8769e02a-52d7-4818-ac19-e5dd46d7075f","displayText":"Juan Francisco Ordóñez","occurrenceId":"d515dcf4-9fc2-4eb6-96ce-34a005568454"}},{"text":" ran with the bassist Héctor Santana, and finally eight years with Juan Luis Guerra. He also wrote music for documentaries — Trujillo: el poder del Jefe III in 1996 and Camino a Higüey in 2016 — and for advertising.","type":"text"}]},{"type":"paragraph","content":[{"text":"Son Familia","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His first album, Trópico adentro, came out in 1995. Pa’ otro la’o was launched internationally on 15 July 1997 with Peralta producing and arranging; «Amor narcótico», «La ciguapa» and «Procura» came off it, and over the following two years the record took gold and platinum certifications in Peru, Chile, Colombia, Bolivia and Central America. Cartagena gave him the keys to the city in June 1998.","type":"text"}]},{"type":"paragraph","content":[{"text":"...De vuelta al barrio","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The third album appeared on 18 April 2000 and won Best Merengue Album at the second Latin Grammy Awards, in 2001. It was recorded in Paris with the London Symphony Orchestra and the Luz África choirs, and set son against jazz, merengue against guaguancó, bachata against Brazilian and Arabic figures. ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bd3ad92b-1a26-48dd-a667-8a0debeaf5a3","displayText":"Jandy Feliz","occurrenceId":"3f304919-b60a-4ccc-9493-609d96560146"}},{"text":" had left to work on his own, and two singers came in to replace him: César Olarte, from Aruba, and René Geraldino.","type":"text"}]},{"type":"paragraph","content":[{"text":"After","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Más que suficiente followed on 27 September 2005 and was nominated for Best Merengue/Bachata Album at the Latin Grammys of 2006; it was among the best-selling Latin records in Japan. In 2007 he was named a goodwill ambassador for the Dominican Republic. De aquel la’o del río came in 2009 carrying «Amor samurái», built from Caribbean music and traditional Japanese instruments, and De que viene, viene followed in 2012 and Máscara contra cabellera in 2013.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Peralta’s records are usually filed under world music for how much they take in: son with jazz, merengue with pop, African rhythms, hip hop, bachata, guaguancó, Brazilian and Arabic figures, symphonic textures, instruments from India and Japan. «Amor narcótico» was recorded again by the American group CNCO on their covers album Déjà Vu in 2021, twenty-four years after he released it.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'chichi-peralta' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Chichi Peralta — Pedro René Peralta Soto, born in Santo Domingo on 9 July 1966 — is a Dominican percussionist, singer, composer, arranger and producer. He spent the 1980s and 1990s as a working percussionist, eight of those years in the band of Juan Luis Guerra 4.40, before launching Chichi Peralta y Son Familia and taking a Latin Grammy in 2001 for ...De vuelta al barrio.

**A tambora at four**

Peralta dates his start to the age of four, when he built his first instrument, a tambora. Through the eighties and nineties he played percussion professionally: first with Grupo Fragmento, then seven years with Fernando Echavarría and la Familia André, then in Trilogía, the fusion trio Juan Francisco Ordóñez ran with the bassist Héctor Santana, and finally eight years with Juan Luis Guerra. He also wrote music for documentaries — Trujillo: el poder del Jefe III in 1996 and Camino a Higüey in 2016 — and for advertising.

**Son Familia**

His first album, Trópico adentro, came out in 1995. Pa’ otro la’o was launched internationally on 15 July 1997 with Peralta producing and arranging; «Amor narcótico», «La ciguapa» and «Procura» came off it, and over the following two years the record took gold and platinum certifications in Peru, Chile, Colombia, Bolivia and Central America. Cartagena gave him the keys to the city in June 1998.

**...De vuelta al barrio**

The third album appeared on 18 April 2000 and won Best Merengue Album at the second Latin Grammy Awards, in 2001. It was recorded in Paris with the London Symphony Orchestra and the Luz África choirs, and set son against jazz, merengue against guaguancó, bachata against Brazilian and Arabic figures. Jandy Feliz had left to work on his own, and two singers came in to replace him: César Olarte, from Aruba, and René Geraldino.

**After**

Más que suficiente followed on 27 September 2005 and was nominated for Best Merengue/Bachata Album at the Latin Grammys of 2006; it was among the best-selling Latin records in Japan. In 2007 he was named a goodwill ambassador for the Dominican Republic. De aquel la’o del río came in 2009 carrying «Amor samurái», built from Caribbean music and traditional Japanese instruments, and De que viene, viene followed in 2012 and Máscara contra cabellera in 2013.

**Legacy**

Peralta’s records are usually filed under world music for how much they take in: son with jazz, merengue with pop, African rhythms, hip hop, bachata, guaguancó, Brazilian and Arabic figures, symphonic textures, instruments from India and Japan. «Amor narcótico» was recorded again by the American group CNCO on their covers album Déjà Vu in 2021, twenty-four years after he released it.' WHERE slug = 'chichi-peralta';
